    if (!token) throw new ApiError(401, "Please sign in.");
    const url = env.SUPABASE_URL || supabase_public_default.url;
    const key = env.SUPABASE_PUBLISHABLE_KEY || supabase_public_default.publishableKey;
    if (url !== supabase_public_default.url && !env.SUPABASE_PUBLISHABLE_KEY) throw new ApiError(503, "Auth configuration does not match the Supabase project.");
    const client = createClient4(url, key, { auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false } });
    const { data, error } = await client.auth.getUser(token);
    if (error || !data.user) throw new ApiError(401, "Your session is invalid or expired. Please sign in again.");
